function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 1000) return 'The tree has at most 1000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Node values are whole numbers from 0 to 1000.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  // In level order, each entry must fill a child slot opened by an earlier node.
  let open = 1;
  for (let i = 0; i < root.length; i++) {
    if (i >= open) return 'Every node needs a parent earlier in the level-order list.';
    if (root[i] !== null) open += 2;
  }
  return null;
}

