function lcaDeepestLeaves(root) {
  // Walk the tree level by level, remembering parents; the last level holds the deepest leaves.
  const parent = new Map();
  let level = [root];
  let last = level;
  while (level.length) {
    last = level;
    const next = [];
    for (const node of level) {
      for (const child of [node.left, node.right]) {
        if (child) { parent.set(child, node); next.push(child); }
      }
    }
    level = next;
  }
  // All deepest leaves share a depth, so lift them together until they meet in one node.
  let group = new Set(last);
  while (group.size > 1) group = new Set([...group].map(node => parent.get(node)));
  return [...group][0];
}

