function generate(rand, size) {
  const n = size === 'large' ? 800 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 12);
  // Distinct values drawn from 0..1000.
  const values = Array.from({ length: 1001 }, (_, i) => i);
  for (let i = values.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  // Grow the tree one node at a time in a free child slot; picking recent slots more often makes deeper trees.
  const recent = rand();
  const left = new Array(n).fill(-1);
  const right = new Array(n).fill(-1);
  const free = [[0, 0], [0, 1]];
  for (let i = 1; i < n; i++) {
    const k = rand() < recent ? free.length - 1 - Math.floor(rand() * Math.min(3, free.length)) : Math.floor(rand() * free.length);
    const [at, side] = free[k];
    free[k] = free[free.length - 1];
    free.pop();
    if (side === 0) left[at] = i; else right[at] = i;
    free.push([i, 0], [i, 1]);
  }
  // Write it out in level order, trimming trailing nulls.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    const id = queue[q];
    if (id === -1) { out.push(null); continue; }
    out.push(values[id]);
    queue.push(left[id], right[id]);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
